from pathlib import Path
import re

path = Path('baseball-game.html')
text = path.read_text(encoding='utf-8')

# 1) More human pitching/batting motion + ball shadows + relay visuals.
old_css = ".playerMan{position:absolute;z-index:9;transform-origin:50% 100%}.playerMan .head{position:absolute;left:50%;transform:translateX(-50%);border-radius:50%;background:#ba7b55}.playerMan .body{position:absolute;left:50%;transform:translateX(-50%);border-radius:20% 20% 35% 35%;background:linear-gradient(#f7f6f2,#d7d8d4)}.playerMan .leg{position:absolute;background:#eceae2;border-radius:4px;transform-origin:50% 0}\n.pitcher{left:50%;top:49.5%;width:58px;height:106px;transform:translate(-50%,-50%) scale(.62)}\n.pitcher .head{top:0;width:20px;height:20px}.pitcher .body{top:18px;width:34px;height:45px}.pitcher .leg.a{left:17px;top:60px;width:9px;height:40px}.pitcher .leg.b{right:17px;top:60px;width:9px;height:40px}\n.pitcher.windup{animation:windup .55s ease-in-out}.pitcher.release{animation:release .25s ease-out}\n@keyframes windup{0%{transform:translate(-50%,-50%) scale(.62)}45%{transform:translate(-50%,-50%) scale(.62) rotate(-6deg)}70%{transform:translate(-50%,-50%) scale(.62) translateY(-4px)}100%{transform:translate(-50%,-50%) scale(.62)}}\n@keyframes release{0%{transform:translate(-50%,-50%) scale(.62) rotate(0)}60%{transform:translate(-50%,-50%) scale(.62) rotate(10deg) translateX(3px)}100%{transform:translate(-50%,-50%) scale(.62)}}"
new_css = ".playerMan{position:absolute;z-index:9;transform-origin:50% 100%}.playerMan .head{position:absolute;left:50%;transform:translateX(-50%);border-radius:50%;background:#ba7b55}.playerMan .body{position:absolute;left:50%;transform:translateX(-50%);border-radius:20% 20% 35% 35%;background:linear-gradient(#f7f6f2,#d7d8d4)}.playerMan .leg{position:absolute;background:#eceae2;border-radius:4px;transform-origin:50% 0}.playerMan .arm{position:absolute;width:8px;height:39px;border-radius:8px;background:#bd815d;transform-origin:50% 8%}\n.pitcher{left:50%;top:49.5%;width:58px;height:106px;transform:translate(-50%,-50%) scale(.62);filter:drop-shadow(0 7px 3px rgba(0,0,0,.28))}\n.pitcher .head{top:0;width:20px;height:20px}.pitcher .body{top:18px;width:34px;height:45px}.pitcher .leg.a{left:17px;top:60px;width:9px;height:40px}.pitcher .leg.b{right:17px;top:60px;width:9px;height:40px}.pitcher .arm.a{left:9px;top:26px;transform:rotate(18deg)}.pitcher .arm.b{right:9px;top:26px;transform:rotate(-22deg)}\n.pitcher.windup{animation:pitchWindup .58s cubic-bezier(.2,.7,.2,1)}.pitcher.release{animation:pitchRelease .34s cubic-bezier(.15,.8,.2,1)}.pitcher.windup .leg.a{animation:pLegLift .58s ease-in-out}.pitcher.windup .arm.a{animation:pGloveGather .58s ease-in-out}.pitcher.windup .arm.b{animation:pArmLoad .58s ease-in-out}.pitcher.release .arm.b{animation:pArmFire .34s ease-out}.pitcher.release .arm.a{animation:pGloveTuck .34s ease-out}\n@keyframes pitchWindup{0%{transform:translate(-50%,-50%) scale(.62) rotate(0)}40%{transform:translate(-50%,-52%) scale(.62) rotate(-4deg)}72%{transform:translate(-50%,-51%) scale(.62) rotate(-8deg)}100%{transform:translate(-50%,-50%) scale(.62) rotate(-5deg)}}\n@keyframes pitchRelease{0%{transform:translate(-50%,-50%) scale(.62) rotate(-5deg)}52%{transform:translate(-47%,-49%) scale(.62) rotate(11deg)}100%{transform:translate(-46%,-48%) scale(.62) rotate(7deg)}}\n@keyframes pLegLift{0%,100%{transform:rotate(0)}52%{transform:rotate(-64deg) translateY(-7px)}}@keyframes pGloveGather{0%{transform:rotate(18deg)}55%{transform:rotate(-68deg) translate(7px,-3px)}100%{transform:rotate(-38deg)}}@keyframes pArmLoad{0%{transform:rotate(-22deg)}55%{transform:rotate(118deg) translate(2px,-4px)}100%{transform:rotate(142deg)}}@keyframes pArmFire{0%{transform:rotate(142deg)}62%{transform:rotate(-70deg) translateY(-4px)}100%{transform:rotate(-112deg)}}@keyframes pGloveTuck{0%{transform:rotate(-38deg)}100%{transform:rotate(46deg) translate(4px,5px)}}"
if old_css not in text:
    raise SystemExit('pitcher css target not found')
text = text.replace(old_css, new_css, 1)

old_batter = ".batter{position:absolute;right:7%;bottom:3%;width:104px;height:235px;z-index:18;transform-origin:50% 92%;filter:drop-shadow(0 7px 5px rgba(0,0,0,.35));transition:transform .1s}"
new_batter = ".batter{--bscale:1;position:absolute;right:7%;bottom:3%;width:104px;height:235px;z-index:18;transform-origin:50% 92%;transform:scale(var(--bscale));filter:drop-shadow(0 7px 5px rgba(0,0,0,.35));transition:transform .1s}"
text = text.replace(old_batter, new_batter, 1)
text = text.replace("@keyframes batterSwing{0%{transform:rotate(0)}55%{transform:rotate(-10deg) translateX(-5px)}100%{transform:rotate(-4deg) translateX(-2px)}}", "@keyframes batterSwing{0%{transform:scale(var(--bscale)) rotate(0) translateX(0)}24%{transform:scale(var(--bscale)) rotate(5deg) translateX(4px)}58%{transform:scale(var(--bscale)) rotate(-14deg) translateX(-8px)}100%{transform:scale(var(--bscale)) rotate(-6deg) translateX(-3px)}}", 1)
text = text.replace("@keyframes batSwing{0%{transform:rotate(28deg)}60%{transform:rotate(-105deg)}100%{transform:rotate(-78deg)}}", "@keyframes batSwing{0%{transform:rotate(28deg)}22%{transform:rotate(40deg)}58%{transform:rotate(-118deg)}100%{transform:rotate(-82deg)}}", 1)
text = text.replace("@media(max-width:620px){.pool{grid-template-columns:1fr 1fr}.batter{right:-2%;transform:scale(.86);transform-origin:100% 100%}", "@media(max-width:620px){.pool{grid-template-columns:1fr 1fr}.batter{--bscale:.86;right:-2%;transform:scale(var(--bscale));transform-origin:100% 100%}", 1)

ball_css = "#ball{position:absolute;width:18px;height:18px;border-radius:50%;background:radial-gradient(circle at 35% 30%,#fff 0 36%,#eee9e0 70%,#d3cec3 100%);display:none;z-index:22;box-shadow:0 0 0 1px rgba(0,0,0,.45),0 2px 6px #0009}"
ball_css_new = ball_css + "\n#ballShadow{position:absolute;width:22px;height:8px;border-radius:50%;background:rgba(0,0,0,.32);filter:blur(2px);display:none;z-index:13;pointer-events:none;transform:translate(-50%,-50%)}"
text = text.replace(ball_css, ball_css_new, 1)

hit_css = ".flyball{position:absolute;width:18px;height:18px;border-radius:50%;background:white;box-shadow:0 0 10px #fff8,0 3px 5px #0006;left:50%;top:78%;z-index:9}"
hit_css_new = hit_css + ".hitBallShadow{position:absolute;width:22px;height:7px;border-radius:50%;background:#0006;filter:blur(2px);left:50%;top:82%;z-index:6;opacity:.55;transform:translate(-50%,-50%)}.relayBall{position:absolute;width:10px;height:10px;border-radius:50%;background:#fff;box-shadow:0 0 8px #fff9,0 2px 3px #0008;z-index:11;opacity:0;transform:translate(-50%,-50%)}"
text = text.replace(hit_css, hit_css_new, 1)
text = text.replace(".hitFielder:after{content:\"\";position:absolute;left:2px;top:8px;width:14px;height:21px;border-radius:4px;background:linear-gradient(#f4f3ed,#cfd4d2);box-shadow:0 12px 0 -5px #eee}", ".hitFielder:after{content:\"\";position:absolute;left:2px;top:8px;width:14px;height:21px;border-radius:4px;background:linear-gradient(var(--defense-team,#f4f3ed),#d8ddd9);box-shadow:0 12px 0 -5px #eee}", 1)
text = text.replace(".hitRunner:after{content:\"\";position:absolute;left:2px;top:8px;width:14px;height:20px;border-radius:4px;background:#e98b2d}", ".hitRunner:after{content:\"\";position:absolute;left:2px;top:8px;width:14px;height:20px;border-radius:4px;background:var(--batter-team,#e98b2d)}", 1)

# 2) Add pitcher arms, pitch shadow, hit shadow, relay ball.
text = text.replace('<div id="pitcher" class="playerMan pitcher"><div class="head"></div><div class="body"></div><div class="leg a"></div><div class="leg b"></div></div>', '<div id="pitcher" class="playerMan pitcher"><div class="head"></div><div class="body"></div><div class="arm a"></div><div class="arm b"></div><div class="leg a"></div><div class="leg b"></div></div>', 1)
text = text.replace('<div id="ball"></div>', '<div id="ballShadow"></div><div id="ball"></div>', 1)
text = text.replace('<div id="resultSplash" class="resultSplash"></div><div id="flyball" class="flyball"></div>', '<div id="resultSplash" class="resultSplash"></div><div id="hitBallShadow" class="hitBallShadow"></div><div id="relayBall" class="relayBall"></div><div id="flyball" class="flyball"></div>', 1)

# 3) Team-color uniforms.
team_anchor = "const teamByName=Object.fromEntries(Object.entries(teams).map(([k,v])=>[v.name,k]));"
team_insert = team_anchor + "\nconst teamPalette={brothers:'#f0cf2e',lions:'#f07d24',monkeys:'#a63a43',dragons:'#c33434',guardians:'#2555a8',hawks:'#2a7d69'};"
text = text.replace(team_anchor, team_insert, 1)

old_update = re.search(r"^function updateBoard\(\)\{.*$", text, re.M)
if not old_update:
    raise SystemExit('updateBoard not found')
new_update = "function updateBoard(){if(!opponent||!lineup.length)return;$('cpuShort').textContent=teams[opponent].short;$('cpuScore').textContent=cpuScore;$('userScore').textContent=userScore;$('inningText').textContent=inning+'局下';$('situation').textContent=outs+'人出局';qsa('.lamp.b').forEach((e,i)=>e.classList.toggle('on',i<balls));qsa('.lamp.s').forEach((e,i)=>e.classList.toggle('on',i<strikes));qsa('.lamp.o').forEach((e,i)=>e.classList.toggle('on',i<outs));[$('base1'),$('base2'),$('base3')].forEach((e,i)=>e.classList.toggle('runner',!!bases[i]));const cur=currentPlayer(),n1=lineup[(batIndex+1)%9],n2=lineup[(batIndex+2)%9],s=cur.stats,r=gameRatings(cur);$('orderText').textContent='第 '+((batIndex%9)+1)+' 棒・'+(positionMap[playerId(cur)]||'—');$('currentBatter').textContent=cur.name;$('batterTeam').textContent=cur.teamName;$('batterRealStats').textContent=s?`AVG ${rate(s.AVG)}・OBP ${rate(s.OBP)}・SLG ${rate(s.SLG)}・OPS ${rate(s.OPS)}`:'AVG —・OBP —・SLG —・OPS —';$('batterGameRating').textContent=`CON ${r.contact}・PWR ${r.power}・SPD ${r.speed}`;$('nextBatters').textContent='後面：'+n1.name+'、'+n2.name;const bc=teamPalette[cur.teamKey]||'#e78928';$('batter').querySelector('.torso').style.background=`linear-gradient(90deg,${bc} 0 68%,#20252a 69%)`;if(cpuPitcher){const pr=currentPitcherRatings(cpuPitcher),fat=pitcherFatigue(cpuPitcher),pc=teamPalette[cpuPitcher.player.teamKey]||'#f2f1ec';$('pitcher').querySelector('.body').style.background=`linear-gradient(${pc},#d7d8d4)`;$('pitcherGameInfo').textContent=`投手 ${cpuPitcher.player.name}｜${cpuPitcher.pitches}球｜V${pr.velo} C${pr.control} B${pr.break}${fat>.55?'｜疲勞':''}`;$('pitcherGameInfo').classList.toggle('pitch-fatigue',fat>.55)}}"
text = text[:old_update.start()] + new_update + text[old_update.end():]

# 4) Pitch starts with a ground shadow and follows the full flight.
text = text.replace("function clearMotion(){if(raf)cancelAnimationFrame(raf);if(timer)clearTimeout(timer);raf=timer=0;pitching=false;$('ball').style.display='none';$('tacticsBtn').disabled=false}", "function clearMotion(){if(raf)cancelAnimationFrame(raf);if(timer)clearTimeout(timer);raf=timer=0;pitching=false;$('ball').style.display='none';if($('ballShadow'))$('ballShadow').style.display='none';$('tacticsBtn').disabled=false}", 1)
text = text.replace("pitchStart=performance.now();$('ball').style.display='block';raf=requestAnimationFrame(animatePitch)", "pitchStart=performance.now();$('ball').style.display='block';$('ballShadow').style.display='block';raf=requestAnimationFrame(animatePitch)", 1)

old_anim = re.search(r"^function animatePitch\(now\)\{.*$", text, re.M)
if not old_anim:
    raise SystemExit('animatePitch not found')
new_anim = "function animatePitch(now){if(!pitching)return;const f=$('scene').getBoundingClientRect(),e=pitchEnd(),t=clamp((now-pitchStart)/pitchDuration,0,1),ease=t*t*(3-2*t),sx=f.width*.5,sy=f.height*.455,x=sx+(e.x-sx)*ease+Math.sin(Math.PI*t)*pitchCurve*(1-t*.2),y=sy+(e.y-sy)*ease+Math.pow(t,2)*pitchDrop,scale=.62+ease*1.02;const b=$('ball'),sh=$('ballShadow');b.style.left=x+'px';b.style.top=y+'px';b.style.transform=`translate(-50%,-50%) scale(${scale})`;if(sh){const groundY=sy+26+(e.y-sy)*ease*.92;sh.style.left=x+'px';sh.style.top=groundY+'px';sh.style.opacity=String(.16+ease*.28);sh.style.transform=`translate(-50%,-50%) scale(${.48+ease*.72})`}if(t>=1){pitching=false;$('tacticsBtn').disabled=false;b.style.display='none';if(sh)sh.style.display='none';takePitch();return}raf=requestAnimationFrame(animatePitch)}"
text = text[:old_anim.start()] + new_anim + text[old_anim.end():]
text = text.replace("$('ball').style.display='none';if(timingErr>.23", "$('ball').style.display='none';$('ballShadow').style.display='none';if(timingErr>.23", 1)

# 5) Realistic hit camera: grounders roll, fly balls arc, fielders throw the ball back.
old_reset = re.search(r"^function resetHitCamera\(\)\{.*$", text, re.M)
if not old_reset:
    raise SystemExit('resetHitCamera not found')
new_reset = "function resetHitCamera(){const cam=$('hitCam'),ball=$('flyball'),runner=$('hitRunner'),shadow=$('hitBallShadow'),relay=$('relayBall');cam.classList.remove('hrMode');cam.getAnimations().forEach(a=>a.cancel());ball.getAnimations().forEach(a=>a.cancel());runner.getAnimations().forEach(a=>a.cancel());if(shadow){shadow.getAnimations().forEach(a=>a.cancel());shadow.style.opacity='.55'}if(relay){relay.getAnimations().forEach(a=>a.cancel());relay.style.opacity='0'}runner.style.opacity='0';runner.style.left='50%';runner.style.top='84%';qsa('[data-hf]').forEach(f=>{f.getAnimations().forEach(a=>a.cancel());f.style.filter=''});const flash=$('catchFlash');flash.classList.remove('pop');flash.style.opacity='0'}"
text = text[:old_reset.start()] + new_reset + text[old_reset.end():]

insert_anchor = "function animateRunner(result,duration){const runner=$('hitRunner');const pts={'1B':[[50,84],[70,70]],'2B':[[50,84],[70,70],[50,51]],'3B':[[50,84],[70,70],[50,51],[30,70]],HR:[[50,84],[70,70],[50,51],[30,70],[50,84]]}[result];if(!pts)return;runner.style.opacity='1';const frames=pts.map((p,i)=>({left:p[0]+'%',top:p[1]+'%',offset:i/(pts.length-1),transform:`translate(-50%,-50%) ${i%2?'rotate(5deg)':'rotate(-5deg)'}`}));runner.animate(frames,{duration,easing:'linear',fill:'forwards'})}"
relay_fn = insert_anchor + "\nfunction animateRelay(fromX,fromY,toX,toY,delay=0,duration=380){const r=$('relayBall');if(!r)return;r.style.left=fromX+'%';r.style.top=fromY+'%';r.style.opacity='0';setTimeout(()=>{r.style.opacity='1';r.animate([{left:fromX+'%',top:fromY+'%',transform:'translate(-50%,-50%) scale(.8)'},{left:((fromX+toX)/2)+'%',top:(Math.min(fromY,toY)-7)+'%',transform:'translate(-50%,-50%) scale(1.15)'},{left:toX+'%',top:toY+'%',transform:'translate(-50%,-50%) scale(.82)'}],{duration,easing:'cubic-bezier(.2,.7,.2,1)',fill:'forwards'});setTimeout(()=>r.style.opacity='0',duration-20)},delay)}"
if insert_anchor not in text:
    raise SystemExit('animateRunner anchor not found')
text = text.replace(insert_anchor, relay_fn, 1)

old_hit = re.search(r"^function showHitThen\(result,label='',b=lastBattedBall\)\{.*$", text, re.M)
if not old_hit:
    raise SystemExit('showHitThen not found')
new_hit = "function showHitThen(result,label='',b=lastBattedBall){resetHitCamera();const cam=$('hitCam'),ball=$('flyball'),shadow=$('hitBallShadow'),splash=$('resultSplash');cam.classList.remove('hidden');const text=result==='HR'?'HOME RUN!':result==='3B'?'三壘安打':result==='2B'?'二壘安打':result==='1B'?'安打':label||'出局';splash.textContent=text;const target=b?[b.targetX,b.targetY]:[50,50],isHr=result==='HR',ground=!!b&&b.launch<7,dur=isHr?1750:ground?clamp(720+(b?.distance||80)*2.2,780,1250):clamp((b?.hang||1)*650,900,1650);cam.classList.toggle('hrMode',isHr);cam.style.setProperty('--batter-team',teamPalette[currentPlayer().teamKey]||'#e98b2d');cam.style.setProperty('--defense-team',teamPalette[opponent]||'#f4f3ed');$('metricEV').textContent=b?Math.round(b.exit)+' mph':'—';$('metricLA').textContent=b?Math.round(b.launch)+'°':'—';$('metricDist').textContent=b?Math.round(b.distance)+' ft':'—';const pan=(target[0]-50)*.045;cam.animate([{transform:'scale(1) translate(0,0)'},{transform:`scale(${isHr?1.055:1.025}) translate(${-pan}%,${isHr?'2%':'1%'})`}],{duration:dur,easing:'ease-out',fill:'forwards'});const fielder=nearestHitFielder(target[0],target[1]);let fx=target[0],fy=target[1];if(fielder&&!isHr){const rect=fielder.getBoundingClientRect(),crect=cam.getBoundingClientRect(),sx=(rect.left+rect.width/2-crect.left)/crect.width*100,sy=(rect.top+rect.height/2-crect.top)/crect.height*100;fx=target[0]+(result==='OUT'?0:(target[0]>50?-4:4));fy=target[1]+4;fielder.animate([{left:sx+'%',top:sy+'%'},{offset:.68,left:fx+'%',top:fy+'%',transform:'translate(-50%,-50%) rotate(0deg)'},{left:fx+'%',top:fy+'%',transform:'translate(-50%,-50%) rotate(-7deg)'}],{duration:Math.min(1000,dur*.75),easing:'cubic-bezier(.2,.7,.2,1)',fill:'forwards'})}let ballFrames;if(isHr)ballFrames=[{left:'50%',top:'78%',transform:'scale(1)'},{left:(50+(b?.spray||0)*.12)+'%',top:'39%',transform:'scale(.74)'},{left:target[0]+'%',top:'4%',transform:'scale(.30)'}];else if(ground)ballFrames=[{left:'50%',top:'78%',transform:'scale(1)'},{offset:.28,left:((target[0]+50)*.5)+'%',top:'70%',transform:'scale(.88)'},{offset:.58,left:((target[0]*.78+50*.22))+'%',top:(target[1]+8)+'%',transform:'scale(.72)'},{left:target[0]+'%',top:target[1]+'%',transform:'scale(.64)'}];else ballFrames=[{left:'50%',top:'78%',transform:'scale(1)'},{left:((target[0]+50)/2)+'%',top:((target[1]+78)/2-14)+'%',transform:'scale(.78)'},{left:target[0]+'%',top:target[1]+'%',transform:'scale(.62)'}];ball.animate(ballFrames,{duration:dur,easing:ground?'cubic-bezier(.18,.45,.25,1)':isHr?'cubic-bezier(.18,.65,.15,1)':'cubic-bezier(.2,.7,.2,1)',fill:'forwards'});if(shadow){const sf=ground?[{left:'50%',top:'80%',opacity:.5,transform:'translate(-50%,-50%) scale(.8)'},{left:target[0]+'%',top:(target[1]+4)+'%',opacity:.65,transform:'translate(-50%,-50%) scale(.65)'}]:[{left:'50%',top:'82%',opacity:.48,transform:'translate(-50%,-50%) scale(.75)'},{left:target[0]+'%',top:(target[1]+5)+'%',opacity:.22,transform:'translate(-50%,-50%) scale(.48)'}];shadow.animate(sf,{duration:dur,easing:'linear',fill:'forwards'})}if(result!=='OUT')animateRunner(result,isHr?2050:result==='3B'?1650:result==='2B'?1380:1020);const fieldTime=Math.min(820,dur*.70);if(result==='OUT'&&fielder){setTimeout(()=>{if(ground){animateRelay(target[0],target[1],70,71,0,360);splash.textContent='傳一壘刺殺';setTimeout(()=>{const flash=$('catchFlash');flash.style.left='70%';flash.style.top='71%';flash.style.opacity='1';flash.classList.remove('pop');void flash.offsetWidth;flash.classList.add('pop');sfx('catch')},330)}else{const flash=$('catchFlash');flash.style.left=target[0]+'%';flash.style.top=target[1]+'%';flash.style.opacity='1';flash.classList.remove('pop');void flash.offsetWidth;flash.classList.add('pop');splash.textContent=label||'接殺出局';sfx('catch')}},fieldTime)}else if(result!=='OUT'&&!isHr&&fielder){setTimeout(()=>animateRelay(fx,fy,50,69,0,420),fieldTime)}if(isHr){sfx('hr');setTimeout(()=>{splash.textContent='全壘打！';sfx('cheer')},780)}else if(result!=='OUT')sfx('hit');else sfx('out');const finishDelay=isHr?2180:ground&&result==='OUT'?Math.max(1450,dur+520):Math.max(1200,dur+220);setTimeout(()=>{cam.classList.add('hidden');resetHitCamera();finishPA(result,label)},finishDelay)}"
text = text[:old_hit.start()] + new_hit + text[old_hit.end():]

path.write_text(text, encoding='utf-8')
print('Applied baseball realism v7 upgrades.')
